$allowedRemoved='renewal|receipt|action group|email receiver|job definition|image digest|entrypoint|owner-attended'
foreach($row in $rows){
  $ok = $false
  switch($row.Status){
    'removed' { $ok = $row.New -match 'ADR-0051' }
    'replaced' { $ok = $row.New -match 'ADR-0051|switch-evidence' -and $source -match 'switch-evidence|entitlement-projection-prefix|compare-snapshot' }
    'adapted' { $ok = $row.New -match 'NamePrefix|Sync-ClaudeAccess' -and $source -match 'NamePrefix|Sync-ClaudeAccess\.ps1 -Store named-value|WhatIf|Confirm|backup|resolver' }
    default { $ok = $row.New -and $source.Length -gt 1000 }
  }
  Assert "coverage mapping: $($row.Old)" $ok $row.New
}
$kept=@($rows|Where-Object Status -eq 'kept').Count; $adapted=@($rows|Where-Object Status -eq 'adapted').Count; $replaced=@($rows|Where-Object Status -eq 'replaced').Count; $removed=@($rows|Where-Object Status -eq 'removed').Count
Write-Host "P97_SWITCH_LABEL_MAPPING kept=$kept adapted=$adapted replaced=$replaced removed=$removed total=$($rows.Count)"
if($fail){ Write-Host "$fail assertion(s) failed." -ForegroundColor Red; exit 1 }; exit 0
